<?php
namespace App\Core\Skills;use App\Models\Skill;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use ZipArchive;
final class SkillInstaller {public function install(int $workspaceId,string $sourceUrl,string $ref='main'):array{if(!SourceProvenanceValidator::validate($sourceUrl))throw new \InvalidArgumentException('Skill source must be HTTPS on a trusted Git host.');$downloadUrl=SkillSourceResolver::downloadUrl($sourceUrl,$ref);$response=Http::withHeaders(['User-Agent'=>'Enverif-Skill-Installer'])->timeout(90)->get($downloadUrl)->throw();$tmp=tempnam(sys_get_temp_dir(),'enverif-skill-');if($tmp===false)throw new \RuntimeException('Unable to create temporary skill archive.');file_put_contents($tmp,$response->body());$zip=new ZipArchive;if($zip->open($tmp)!==true){@unlink($tmp);throw new \RuntimeException('Skill source is not a readable ZIP archive.');}$installed=[];for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);if(!$name||!str_ends_with($name,'SKILL.md'))continue;if(str_contains($name,'../')||str_starts_with($name,'/'))continue;$content=$zip->getFromIndex($i);if(!is_string($content))continue;$parsed=SkillFrontmatter::parse($content);$scan=(new SkillSecurityScanner)->scan($content);$skill=Skill::updateOrCreate(['workspace_id'=>$workspaceId,'slug'=>$parsed['name']],['name'=>$parsed['name'],'description'=>$parsed['description'],'version'=>$parsed['version'],'source_type'=>'git','source_url'=>$sourceUrl,'source_ref'=>$ref,'checksum'=>SourceProvenanceValidator::checksum($content),'license'=>null,'capabilities'=>$parsed['capabilities'],'body'=>$parsed['body'],'status'=>$scan['safe']?'active':'quarantined','built_in'=>false]);$installed[]=['skill'=>$skill,'findings'=>$scan['findings']];}$zip->close();@unlink($tmp);if(!$installed)throw new \RuntimeException('No valid SKILL.md was found in the source repository.');return $installed;}}
